import {BRIEF_EXAMPLES,LOCAL_MODEL,currentBrief,exampleMatches} from './change-brief.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>';
function sourceCard(record,review,{top=false,index=0}={}){
 return `<article class="brief-source ${top?'brief-top-match':''}" data-dom-key="source-${record.id}"><div class="brief-source-head"><span>${record.patient==='All'?'HANDOFF':`ROOM ${record.patient}`} · ${esc(record.field)}</span>${top?'<strong>Closest match</strong>':`<small>Source ${index+1}</small>`}</div><h3>${esc(record.name)}</h3><details class="brief-evidence" ${top?'open':''}><summary>Compare source versions<span>v${review.before.number} → v${review.after.number}</span></summary>${record.before?`<div class="brief-before"><span>v${review.before.number} · ${review.before.time}</span><p>${esc(record.before)}</p></div>`:`<div class="brief-before"><span>v${review.before.number}</span><p>No entry for this added item.</p></div>`}<div class="brief-after"><span>v${review.after.number} · ${review.after.time}</span><p>${esc(record.after)}</p></div></details>${record.patientId?`<button class="button text small brief-source-link" data-action="brief-source" data-patient="${record.patientId}" data-version="${review.after.id}">Open patient in v${review.after.number} ${arrow}</button>`:''}</article>`;
}
export function briefBody(review,{mode='demo',example='owner',query='',runtime,showAll=false,sampleHref='/shift?scene=assist&screen=detail&brief=1&briefmode=local'}={}){
 if(!review)return `<div class="brief-welcome"><span class="brief-welcome-label">ON-DEVICE AI</span><h3>Find the change behind your question.</h3><p>Ask about an owner, an expected time or an added note. Local AI finds the related change and keeps the source beside it.</p><div class="brief-welcome-context"><strong>Your handoff is not ready for a comparison yet.</strong><p>Two submitted versions, both readable by this colleague, are needed. You can try the complete workflow in a separate fictional sample.</p></div><a class="button primary" href="${esc(sampleHref)}" target="_blank" rel="noopener">Try AI on a sample <span aria-hidden="true">↗</span><span class="sr-only"> (opens in a new tab)</span></a><p class="small-note">Your saved workspace stays in this tab. Model loading is optional and starts only when you choose Load model &amp; search.</p></div>`;
 const busy=['loading','searching','removing'].includes(runtime.phase),valid=currentBrief(runtime.result,review);
 const stale=runtime.result&&!valid;
 const result=mode==='demo'?exampleMatches(review,example):valid?runtime.result.matches:null;
 const matched=(result||[]).map(m=>review.records.find(c=>c.id===m.id)).filter(Boolean);
 const rest=review.records.filter(c=>!matched.some(m=>m.id===c.id));
 return `<div class="brief-scope"><div><span>CHANGE BRIEF</span><strong>v${review.before.number} <span>→</span> v${review.after.number}</strong></div><p>${review.records.length} recorded change${review.records.length!==1?'s':''} · ${review.roomCount} room${review.roomCount!==1?'s':''}<br><span>Submitted snapshots · read-only</span></p></div>
 <div class="brief-modes" role="group" aria-label="Brief mode"><button type="button" data-action="brief-mode" data-value="demo" aria-pressed="${mode==='demo'}">Guided demo</button><button type="button" data-action="brief-mode" data-value="local" aria-pressed="${mode==='local'}">On-device AI <span>Optional</span></button></div>
 ${mode==='demo'?`<div class="brief-intro"><h3>Find the change. Keep its source.</h3><p>Try a prepared example, then open the exact version behind it.</p><span class="brief-disclosure">Prepared matches · no model is running</span></div><div class="brief-examples" aria-label="Prepared example questions">${BRIEF_EXAMPLES.map(e=>`<button data-action="brief-example" data-value="${e.id}" aria-pressed="${example===e.id}" aria-label="${esc(e.label)}">${e.id==='owner'?'Owner':e.id==='time'?'Expected time':'Added note'}</button>`).join('')}</div>`:
 `<div class="brief-intro ${valid?'brief-intro-compact':''}"><h3>Ask in your own words.</h3><p>A small model finds related changes by meaning. The answer stays in the source’s own words.</p></div><form data-form="brief-search" class="brief-search"><label class="field-label" for="brief-query">Find a recorded change <span>English questions</span></label><textarea id="brief-query" name="query" rows="2" maxlength="180" required placeholder="Who took over the family update?">${esc(query)}</textarea><div class="brief-search-actions"><button class="button primary" type="submit" ${busy||!review.records.length?'disabled':''}>${runtime.loaded?'Search on this device':'Load model & search'} ${arrow}</button>${busy&&runtime.phase!=='removing'?'<button class="button secondary" type="button" data-action="brief-stop">Stop</button>':''}</div></form><div class="brief-download-note"><span class="brief-local-dot"></span><div>${runtime.loaded?'Model ready · questions stay on this device.':'About 50 MB first download · 23 MB model weights.'}${runtime.loaded?'':`<small>Files load from Hugging Face and jsDelivr after you start. Questions and records are processed on this device. No API key or paid inference service.</small>`}</div></div>
 ${runtime.message?`<div class="brief-runtime-status ${runtime.phase==='error'?'brief-error':''}" role="status"><p>${esc(runtime.message)}</p>${runtime.phase==='complete'?'<button class="button text small" data-action="brief-results">Show matches</button>':''}${runtime.progress!==null&&busy?`<label>Current file <progress max="100" value="${runtime.progress}">${runtime.progress}%</progress></label>`:''}</div>`:''}
 `}
 ${stale&&mode==='local'?'<div class="inline-note brief-stale">The version comparison changed. Search again to update the matches.</div>':''}
 ${result?`<section class="brief-results" aria-label="${mode==='demo'?'Prepared example result':'Local search results'}"><div class="brief-results-label"><h3 tabindex="-1" id="brief-result-heading">${matched.length?'Source-based result':'No close source match'}</h3><span>${mode==='demo'?'Guided example':'Matched on this device'}</span></div>${mode==='local'&&valid?`<p class="brief-question">“${esc(runtime.result.query)}”</p>`:mode==='demo'?`<p class="brief-question">“${esc(BRIEF_EXAMPLES.find(e=>e.id===example)?.label||'')}”</p>`:''}${matched.length?matched.map((record,i)=>sourceCard(record,review,{top:i===0,index:i})).join(''):'<p class="brief-no-match">Try a more specific question, or read all changes below. The search does not answer beyond these records.</p>'}</section>`:''}
 ${rest.length?`<div class="brief-all-heading"><span>${result?'Other recorded changes':'Recorded changes'}</span><button class="button text small" data-action="brief-all" aria-expanded="${showAll}">${showAll?'Hide':'Show'} ${rest.length} change${rest.length!==1?'s':''}</button></div>${showAll?`<div class="brief-other">${rest.map((record,i)=>sourceCard(record,review,{index:i+matched.length})).join('')}</div>`:''}`:''}
 ${mode==='local'?`${runtime.loaded&&!busy?'<div class="brief-model-controls"><button class="button text small" data-action="brief-unload">Unload model</button><button class="button text small" data-action="brief-remove">Remove downloaded model</button></div>':''}
 <details class="brief-how"><summary>How local search works</summary><p>${LOCAL_MODEL.name} compares the meaning of your question with up to 64 changes. Long records are shortened for matching; the full source remains available. It ranks source records; it does not generate prose, assess a patient or change the handoff. Matching can be imperfect. Check the original versions before confirming review.</p><p>Downloaded model files may be cached by your browser. First use needs a connection; later offline use depends on what remains cached. Unloading releases the worker. Removing the model clears its cached files when the browser allows it.</p></details>`:''}
 <p class="brief-boundary">This brief never acknowledges a version or edits a record. Your review stays deliberate.</p>`;
}
export function briefCasePreview(){return `<div class="case-ai-preview"><div class="case-ai-preview-top"><span>CHANGE BRIEF</span><strong>v1 → v2</strong></div><p class="case-ai-query">Who took over the family update?</p><div class="case-ai-evidence"><span>ROOM 414 · ACTION OWNER</span><h3>Avery Reid</h3><div><span>v1</span><p>Jordan Lee</p></div><div><span>v2</span><p>Taylor Brooks</p></div><p class="case-ai-source-label">Source: submitted handoff versions</p></div><div class="case-ai-preview-footer"><span>On-device semantic search</span><span>Source-linked result</span></div></div>`;}
